<script setup lang="ts">
import { useForm, usePage } from '@inertiajs/vue3'; import { Pencil, Plus, Target } from 'lucide-vue-next'; import { computed, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import Button from '@/Core/Components/Button.vue'; import Card from '@/Core/Components/Card.vue'; import DataTable, { type Column } from '@/Core/Components/DataTable.vue'; import EmptyState from '@/Core/Components/EmptyState.vue'; import Input from '@/Core/Components/Input.vue'; import Modal from '@/Core/Components/Modal.vue'; import PageHeader from '@/Core/Components/PageHeader.vue'; import Pagination from '@/Core/Components/Pagination.vue'; import { useFormat } from '@/Core/composables/useFormat'; import TenantLayout from '@/Core/Layouts/TenantLayout.vue'; import { route } from '@/Core/lib/route'; import type { Paginated } from '@/Core/types'; import SalesNav from '../../../Components/SalesNav.vue'; import type { SalesTarget } from '../../../Components/types';
defineOptions({ layout: TenantLayout }); const props = defineProps<{ targets: Paginated<SalesTarget>; canCreate: boolean }>(); const { t } = useI18n(); const format = useFormat(); const page = usePage(); const open = ref(false); const target = ref<SalesTarget | null>(null); const form = useForm({ name: '', currency: page.props.app.currency, target_amount: 0, period_start: '', period_end: '' }); const columns = computed<Column[]>(() => [{ key: 'name', label: t('crm.fields.name') }, { key: 'period', label: t('crm.fields.period') }, { key: 'target', label: t('crm.sales.targets.target'), align: 'right' }, { key: 'actual', label: t('crm.sales.targets.actual'), align: 'right' }, { key: 'attainment', label: t('crm.sales.targets.attainment'), align: 'right' }, { key: 'owner', label: t('crm.fields.owner'), hideable: true }, { key: 'actions', label: t('crm.common.actions'), srOnly: true, align: 'right' }]); function edit(item: SalesTarget | null): void { target.value = item; form.name = item?.name ?? ''; form.currency = item?.currency ?? page.props.app.currency; form.target_amount = item?.targetAmount ?? 0; form.period_start = item?.periodStart ?? ''; form.period_end = item?.periodEnd ?? ''; form.clearErrors(); open.value = true; } function submit(): void { const settings = { preserveScroll: true, onSuccess: () => { open.value = false; form.reset(); } }; if (target.value) form.put(route('crm.sales.targets.update', { salesTarget: target.value.id }), settings); else form.post(route('crm.sales.targets.store'), settings); }
</script>
<template><PageHeader :eyebrow="t('crm.eyebrow')" :title="t('crm.sales.targets.title')" :description="t('crm.sales.targets.description')"><template v-if="canCreate" #actions><Button variant="primary" @click="edit(null)"><template #icon><Plus class="size-4" aria-hidden="true" /></template>{{ t('crm.sales.targets.add') }}</Button></template></PageHeader><SalesNav current="targets" /><Card flush><DataTable :columns="columns" :rows="targets.data" row-key="id" :caption="t('crm.sales.targets.title')" storage-key="crm-targets"><template #cell-name="{ row }"><span class="font-medium text-ink">{{ row.name }}</span></template><template #cell-period="{ row }"><span class="tabular text-ink-muted">{{ format.date(row.periodStart) }} — {{ format.date(row.periodEnd) }}</span></template><template #cell-target="{ row }"><span class="tabular font-mono">{{ format.money(row.targetAmount, row.currency) }}</span></template><template #cell-actual="{ row }"><span class="tabular font-mono">{{ format.money(row.actualAmount, row.currency) }}</span></template><template #cell-attainment="{ row }"><span class="tabular font-mono" :class="row.attainmentBps >= 10000 ? 'text-ok' : 'text-ink'">{{ format.number(row.attainmentBps / 100) }}%</span></template><template #cell-owner="{ row }"><span class="text-ink-muted">{{ row.owner?.name ?? t('crm.common.unassigned') }}</span></template><template #cell-actions="{ row }"><Button v-if="row.editable" icon size="sm" variant="ghost" :aria-label="t('crm.sales.targets.edit')" @click="edit(row)"><template #icon><Pencil class="size-4" aria-hidden="true" /></template></Button></template><template #empty><EmptyState :title="t('crm.sales.targets.empty')"><template #icon><Target /></template></EmptyState></template></DataTable><Pagination :meta="targets" /></Card><Modal v-model:open="open" :title="t(target ? 'crm.sales.targets.edit' : 'crm.sales.targets.add')" :persistent="form.processing"><form id="crm-target-form" class="grid gap-4 sm:grid-cols-2" @submit.prevent="submit"><Input v-model="form.name" class="sm:col-span-2" :label="t('crm.fields.name')" :error="form.errors.name" required maxlength="120" /><Input v-model="form.currency" :label="t('crm.fields.currency')" :error="form.errors.currency" required maxlength="3" /><Input v-model="form.target_amount" type="number" min="0" :label="t('crm.sales.targets.target')" :error="form.errors.target_amount" required /><Input v-model="form.period_start" type="date" :label="t('crm.sales.targets.periodStart')" :error="form.errors.period_start" required /><Input v-model="form.period_end" type="date" :label="t('crm.sales.targets.periodEnd')" :error="form.errors.period_end" required /></form><template #footer><Button variant="ghost" @click="open = false">{{ t('crm.common.cancel') }}</Button><Button form="crm-target-form" type="submit" variant="primary" :loading="form.processing">{{ t('crm.common.save') }}</Button></template></Modal></template>
